public class Main {
    static class Proto { static int n = 0; int id = ++n; }
    static class Singleton {
        Proto proto;
        Proto get() { return proto; }
    }
    public static void main(String[] args) {
        Singleton s = new Singleton();
        s.proto = new Proto();
        Proto first = s.get();
        Proto second = s.get();
        System.out.println("singleton holds same proto: " + (first == second));
        System.out.println("proto id fixed: " + first.id);
        System.out.println("proto changes per call: " + (first.id != second.id));
    }
}
